    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: In the ATLS primary survey, what does "A" stand for?', '["Airway with C-spine protection", "Assessment of breathing", "Abdominal exam", "None"]', 0, 'The first priority is securing the airway while protecting the spinal cord. (Schwartz''s Ch. 7)'),
    (v_topic_id, '2: What is the definitive airway in a trauma patient?', '["Oral airway", "Endotracheal tube with the balloon inflated in the trachea", "Nasopharyngeal airway", "None"]', 1, 'Laryngeal mask airways (LMAs) are not definitive. (de Virgilio Ch. 2)'),
    (v_topic_id, '3: A patient with a GCS of <= ____ requires definitive airway management.', '["3", "8", "12", "15"]', 1, '"GCS of 8, irrigate the plate" (or intubate). (Mont Reid Ch. 8)'),
    (v_topic_id, '4: In a "can''t intubate, can''t ventilate" scenario, what is the preferred emergency surgical airway?', '["Tracheostomy", "Cricothyroidotomy", "Needle decompression", "None"]', 1, 'Cricothyroidotomy is faster and easier in the emergency setting. (Schwartz''s Ch. 7)'),
    (v_topic_id, '5: Why is "Nasotracheal" intubation contraindicated in patients with midface fractures?', '["Risk of gagging", "Risk of intracranial tube placement (through cribriform plate)", "Pain", "None"]', 1, 'A classic contraindication. (de Virgilio Ch. 2)'),
    (v_topic_id, '6: "B" in ABCDE stands for Breathing. What is the first-line treatment for a "Tension Pneumothorax"?', '["Chest X-ray", "Needle decompression (2nd ICS/MCL or 4th/5th ICS/AAL)", "Chest tube", "Intubation"]', 1, 'Should be a clinical diagnosis; do NOT wait for X-ray. (Mont Reid Ch. 8)'),
    (v_topic_id, '7: A "Massive Hemothorax" is defined by the initial drainage of > ____ mL of blood or > 200 mL/hr for 2-4 hours.', '["500", "1000", "1500", "None"]', 2, 'Indication for urgent thoracotomy. (Schwartz''s Ch. 7)'),
    (v_topic_id, '8: "Flail Chest" is characterized by ____ segment of chest wall movement during respiration.', '["Symmetric", "Paradoxical (inward on inspiration)", "None", "None"]', 1, 'Occurs when >= 3 adjacent ribs are fractured in 2 places. (de Virgilio Ch. 3)'),
    (v_topic_id, '9: What is the underlying cause of hypoxia in "Flail Chest"?', '["Rib pain", "Pulmonary Contusion", "Tracheal deviation", "None"]', 1, 'Bruised lung tissue impairs gas exchange. (Mont Reid Ch. 8)'),
    (v_topic_id, '10: "Cardiac Tamponade" - Beck''s Triad includes Hypotension, Muffled heart sounds, and ____.', '["Bradycardia", "Distended neck veins (JVD)", "Wheezing", "None"]', 1, 'Indicates increased intrapericardial pressure. (Schwartz''s Ch. 7)');
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '11: "Hypovolemic Shock" (Class III) is characterized by a blood loss of ____%.', '["< 15%", "15-30%", "30-40%", "> 40%"]', 2, 'Presents with marked tachycardia, tachypnea, and hypotension. (de Virgilio Ch. 2)'),
    (v_topic_id, '12: What is the first-line fluid for resuscitation in trauma?', '["D5W", "Isotonic Crystalloids (Normal Saline or Lactated Ringer''s)", "Whole blood", "Colloids"]', 1, 'Warm fluids help prevent hypothermia. (Mont Reid Ch. 8)'),
    (v_topic_id, '50: In "Neurogenic Shock," what is a classic distinguishing feature compared to other shocks?', '["Tachycardia", "Bradycardia and Hypotension", "Fever", "None"]', 1, 'Loss of sympathetic tone leads to bradycardia. (Mont Reid Ch. 8)');
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '14: "Massive Transfusion Protocol" (MTP) typically aims for a ratio of RBC:FFP:Platelets of ____.', '["10:1:1", "1:1:1", "4:2:1", "None"]', 1, 'Mimics whole blood and prevents coagulopathy. (de Virgilio Ch. 2)'),
    (v_topic_id, '15: The "Lethal Triad" of trauma includes Acidosis, Coagulopathy, and ____.', '["Hyperthermia", "Hypothermia", "Sepsis", "None"]', 1, 'Must be aggressively corrected during damage control. (Mont Reid Ch. 8)'),
    (v_topic_id, '16: "Damage Control Laparotomy" (DCL) focuses on controlling hemorrhage and contamination. What is the final step?', '["Definitive organ repair", "Temporary abdominal closure", "Skin suturing", "None"]', 1, 'Patient is taken to ICU for stabilization before returning to the OR. (Schwartz''s Ch. 7)'),
    (v_topic_id, '17: "FAST" Exam (Focused Assessment with Sonography for Trauma) checks for fluid in the RUQ, LUQ, Pelvis, and ____.', '["Spleen", "Pericardium", "Lung", "None"]', 1, 'Detects hemoperitoneum and tamponade. (de Virgilio Ch. 2)'),
    (v_topic_id, '18: An unstable patient with a "Positive" FAST exam should go to the:', '["CT scanner", "Operating Room", "ICU", "None"]', 1, 'No time for imaging in the unstable patient. (Mont Reid Ch. 8)'),
    (v_topic_id, '19: "Zone II" of the neck is located between the cricoid cartilage and the ____.', '["Clavicle", "Angle of the mandible", "Base of skull", "None"]', 1, 'Most accessible zone for surgical exploration. (Schwartz''s Ch. 7)'),
    (v_topic_id, '20: What is the most commonly injured organ in "Blunt" abdominal trauma?', '["Liver", "Spleen", "Bowel", "Kidney"]', 1, 'Kehr''s sign (left shoulder pain) may be present. (de Virgilio Ch. 4)'),
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '51: "Airway" - What is the narrowest part of the pediatric airway?', '["Glottis", "Cricoid cartilage", "Trachea", "None"]', 1, 'Funnel shape in children. (Schwartz''s Ch. 37)'),
    (v_topic_id, '52: "Airway" - BURP maneuver stands for Backward, Upward, Rightward ____.', '["Pressure", "Puncture", "Pull", "None"]', 0, 'Improves laryngeal view during intubation. (de Virgilio Ch. 2)'),
    (v_topic_id, '53: "Breathing" - Open Pneumothorax (Sucking chest wound) treatment?', '["Chest tube only", "Occlusive dressing taped on 3 sides", "Intubation", "None"]', 1, 'Acts as a one-way valve to prevent tension PTX. (Mont Reid Ch. 8)'),
    (v_topic_id, '54: "Breathing" - Chest tube size for hemothorax?', '["Small (14F)", "Large (28-36F)", "None", "None"]', 1, 'Needs to be large enough to drain blood/clots. (Schwartz''s Ch. 7)'),
    (v_topic_id, '55: "Circulation" - Best indicator of successful resuscitation?', '["Heart rate", "Urine output (0.5 mL/kg/hr)", "Blood pressure", "None"]', 1, 'Indicates end-organ perfusion. (de Virgilio Ch. 2)'),
    (v_topic_id, '56: "Circulation" - IV access in trauma?', '["Central line", "Two large bore (14-16G) peripheral IVs", "PICC line", "None"]', 1, 'Short, wide catheters allow faster flow (Poiseuille''s Law). (Mont Reid Ch. 8)'),
    (v_topic_id, '57: "Disability" - GCS: Motor score for "withdraws from pain"?', '["2", "3", "4", "5"]', 2, '1-None, 2-Extends, 3-Flexes, 4-Withdraws, 5-Localizes, 6-Obeys. (Schwartz''s Ch. 7)'),
    (v_topic_id, '58: "Disability" - GCS: Verbal score for "inappropriate words"?', '["1", "2", "3", "4"]', 2, '1-None, 2-Sounds, 3-Words, 4-Confused, 5-Oriented. (de Virgilio Ch. 2)'),
    (v_topic_id, '59: "Trauma Thoracotomy" - Indication?', '["Lost vitals in the ER after penetrating trauma", "Blunt trauma with pulse", "None", "None"]', 0, 'Resuscitative thoracotomy. (Mont Reid Ch. 8)'),
    (v_topic_id, '60: "Thoracotomy" - What is done first?', '["Repair heart", "Pericardiotomy / Cross-clamp aorta", "Close lung", "None"]', 1, 'Control hemorrhage and redistribute blood to brain. (Schwartz''s Ch. 7)'),
    (v_topic_id, '61: "Neck Trauma" - Zone I location?', '["Clavicle to Cricoid", "Cricoid to Mandible", "Above Mandible", "None"]', 0, 'Highest mortality due to great vessels. (de Virgilio Ch. 3)'),
    (v_topic_id, '62: "Neck Trauma" - Zone III location?', '["Base of skull", "Above Angle of Mandible", "Clavicle", "None"]', 1, 'Difficult surgical access. (Mont Reid Ch. 8)'),
    (v_topic_id, '63: "Chest Trauma" - Diaphragmatic rupture #1 side?', '["Right", "Left", "Same", "None"]', 1, 'Liver protects the right side. (Schwartz''s Ch. 7)'),
    (v_topic_id, '64: "Chest Trauma" - Aortic injury site?', '["Ascending", "Isthmus (just distal to L subclavian)", "Abdominal", "None"]', 1, 'Fixed vs mobile junction. (de Virgilio Ch. 3)'),
    (v_topic_id, '65: "Abdominal Trauma" - Duodenal hematoma? ', '["Immediate surgery", "Observation / NGT / TPN", "None", "None"]', 1, 'Often resolves in 2-3 weeks; common in kids. (Mont Reid Ch. 8)'),
    (v_topic_id, '66: "Abdominal Trauma" - Seatbelt sign? ', '["Bruise across belly", "High risk of hollow viscus injury (bowel)", "Both", "None"]', 2, 'Clinical warning. (Schwartz''s Ch. 7)'),
    (v_topic_id, '67: "Spleen" - Grade I trauma? ', '["Subcapsular hematoma < 10% surface", "Mashed", "None", "None"]', 0, 'Minimal injury. (de Virgilio Ch. 4)'),
    (v_topic_id, '68: "Spleen" - Grade V trauma? ', '["Shattered spleen or hilar devascularization", "Small cut", "None", "None"]', 0, 'Requires splenectomy. (Mont Reid Ch. 8)'),
    (v_topic_id, '69: "Liver" - Pringle maneuver? ', '["Clamps portal triad", "Controls bleeding from portal vein/hepatic artery", "Both", "None"]', 2, 'Damage control. (Schwartz''s Ch. 31)'),
    (v_topic_id, '70: "Genitourinary" - Blood at meatus? ', '["Insert foley", "Retrograde Urethrogram (RUG)", "CT", "None"]', 1, 'Do NOT insert foley if urethral injury is suspected. (de Virgilio Ch. 32)'),
    (v_topic_id, '71: "Pelvic Trauma" - Open book? ', '["Pubic symphysis diastasis", "Venous plexus bleed #1", "Both", "None"]', 2, 'Unstable. (Mont Reid Ch. 8)'),
    (v_topic_id, '72: "Pelvic Trauma" - arterial bleed? ', '["Needs embolization (Interventional Radiology)", "Surgery", "None", "None"]', 0, 'Difficult to control in OR. (Schwartz''s Ch. 7)'),
    (v_topic_id, '73: "Head Trauma" - ICP target? ', '["< 5", "< 20 mmHg", "> 50", "None"]', 1, 'Standard goal. (de Virgilio Ch. 2)'),
    (v_topic_id, '74: "Cerebral Perfusion Pressure" (CPP) = MAP - ____.', '["CVP", "ICP", "SBP", "None"]', 1, 'Goal is 50-70 mmHg. (Mont Reid Ch. 8)'),
    (v_topic_id, '75: "Head Trauma" - Mannitol? ', '["Osmotic diuretic", "Lowers ICP", "Both", "None"]', 2, 'Management. (Schwartz''s Ch. 7)'),
    (v_topic_id, '76: "Spinal Trauma" - Central Cord Syndrome? ', '["Weakness Upper > Lower", "Elderly with hyperextension", "Both", "None"]', 2, 'Common pattern. (de Virgilio Ch. 2)'),
    (v_topic_id, '77: "Spinal Trauma" - Anterior Cord Syndrome? ', '["Loss of motor/pain/temp", "Proprioception preserved", "Both", "None"]', 2, 'Vascular injury. (Mont Reid Ch. 8)'),
    (v_topic_id, '78: "Burns" - 1st degree? ', '["Sunburn (Painful, red, no blisters)", "Both", "None", "None"]', 0, 'Superficial. (Schwartz''s Ch. 8)'),
    (v_topic_id, '79: "Burns" - 2nd degree (Partial)? ', '["Painful + Blisters", "Both", "None", "None"]', 0, 'Dermal involvement. (de Virgilio Ch. 6)'),
    (v_topic_id, '80: "Burns" - 3rd degree (Full thickness)? ', '["Painless (nerves destroyed) + Leathery", "Both", "None", "None"]', 0, 'Complete destruction. (Mont Reid Ch. 8)'),
    (v_topic_id, '81: "Inhalation Injury" - signs? ', '["Soot in mouth, Singed nose hairs, Stridor", "Both", "None", "None"]', 2, 'Requires early intubation. (Schwartz''s Ch. 8)'),
    (v_topic_id, '82: "Carbon Monoxide" - treatment? ', '["Room air", "100% Oxygen (reduces half-life from 4h to 40m)", "None", "None"]', 1, 'Displaces CO from Hb. (de Virgilio Ch. 6)'),
    (v_topic_id, '83: "Cyanide Toxicity" - sign? ', '["Persistent lactic acidosis in house fire victim", "Both", "None", "None"]', 0, 'Treatment: Hydroxocobalamin. (Mont Reid Ch. 8)'),
    (v_topic_id, '84: "Electrical Burn" - major risk? ', '["Rhabdomyolysis / Renal failure", "Both", "None", "None"]', 0, '"Iceberg" injury. (Schwartz''s Ch. 8)'),
    (v_topic_id, '85: "Acid Burn" - type of necrosis? ', '["Liquefactive", "Coagulative", "Both", "None"]', 1, 'Contrast with base. (de Virgilio Ch. 6)'),
    (v_topic_id, '86: "Alkali Burn" - type of necrosis? ', '["Coagulative", "Liquefactive (deeper)", "Both", "None"]', 1, 'More dangerous. (Mont Reid Ch. 8)'),
    (v_topic_id, '87: "Shock" - Cardiogenic? ', '["Low CO, High CVP/PCWP", "Both", "None", "None"]', 0, 'Pump failure. (Schwartz''s Ch. 5)'),
    (v_topic_id, '88: "Shock" - Distributive (Sepsis)? ', '["High CO, Low SVR", "Both", "None", "None"]', 0, 'Vasodilation. (de Virgilio Ch. 1)'),
    (v_topic_id, '89: "Septic Shock" - #1 vasopressor?', '["Dopamine", "Norepinephrine (Levophed)", "Epinephrine", "None"]', 1, 'First line therapy. (Mont Reid Ch. 8)'),
    (v_topic_id, '90: "Adrenal Crisis" - treatment? ', '["Fluids + Stress dose steroids (Hydrocortisone)", "Both", "None", "None"]', 2, 'Management. (Schwartz''s Ch. 38)'),
    (v_topic_id, '91: "Acid-Base" - pH 7.2, pCO2 60? ', '["Metabolic acidosis", "Respiratory acidosis", "Alkalosis", "None"]', 1, 'Hypercapnic failure. (de Virgilio Ch. 1)'),
    (v_topic_id, '92: "Acid-Base" - pH 7.5, pCO2 25? ', '["Respiratory alkalosis", "Metabolic acidosis", "None", "None"]', 0, 'Hyperventilation. (Mont Reid Ch. 8)'),
    (v_topic_id, '93: "Anion Gap" - Metabolic Acidosis? ', '["Diarrhea", "MUDPILES", "Vomiting", "None"]', 1, 'Common causes. (Schwartz''s Ch. 11)'),
    (v_topic_id, '94: "Non-Gap" Metabolic Acidosis? ', '["Diarrhea", "RTA", "Both", "None"]', 2, 'Bicarb loss. (de Virgilio Ch. 1)'),
    (v_topic_id, '95: "Hypocalcemia" - EKG? ', '["Short QT", "Long QT", "Both", "None"]', 1, 'Electrolyte sign. (Mont Reid Ch. 8)'),
    (v_topic_id, '96: "Hypomagnesemia" - refractory? ', '["Potassium and Calcium won''t fix until Mg is fixed", "True", "Both", "None"]', 2, 'Clinical pearl. (Schwartz''s Ch. 11)'),
    (v_topic_id, '97: "Hyperkalemia" - 1st treatment to stabilize heart?', '["Insulin", "Calcium Gluconate", "Kayexalate", "None"]', 1, 'Antagonizes membrane effects. (de Virgilio Ch. 1)'),
    (v_topic_id, '98: "Hyponatremia" - rapid correction risk? ', '["Seizure", "Central Pontine Myelinolysis (Osmotic Demyelination)", "None", "None"]', 1, '"Low to High, your pons will die." (Mont Reid Ch. 8)'),
    (v_topic_id, '99: "Hypernatremia" - rapid correction risk? ', '["Cerebral Edema", "Stroke", "None", "None"]', 0, '"High to Low, your brain will blow." (Schwartz''s Ch. 11)'),
    (v_topic_id, '100: "Trauma" - death distribution? ', '["Trimodal (Seconds, Minutes-Hours, Days-Weeks)", "Both", "None", "None"]', 2, 'Epidemiology. (de Virgilio Ch. 2)');
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: "Airway" - LEMON score? ', '["Predicts difficult intubation", "True", "Both", "None"]', 2, 'Look, Evaluate 3-3-2, Mallampati, Obstruction, Neck. (Schwartz''s Ch. 7)'),
    (v_topic_id, '102: "Mallampati IV" = ?', '["Hard palate only visible", "Soft palate visible", "Both", "None"]', 0, 'Difficult airway. (de Virgilio Ch. 2)'),
    (v_topic_id, '103: "Cricothyroidotomy" - location? ', '["Between thyroid and cricoid cartilage", "Both", "None", "None"]', 0, 'Anatomy. (Mont Reid Ch. 8)'),
    (v_topic_id, '104: "Tracheostomy" - location? ', '["Between 2nd and 3rd tracheal rings", "Both", "None", "None"]', 0, 'Anatomy. (Schwartz''s Ch. 7)'),
    (v_topic_id, '105: "Needle Decompression" - New ATLS recommendation? ', '["4th/5th ICS mid-axillary line in adults", "2nd ICS", "None", "None"]', 0, 'Updated for thicker chest walls. (de Virgilio Ch. 2)'),
    (v_topic_id, '106: "Beck''s Triad" - Tamponade? ', '["Hypotension, JVD, Muffled heart sounds", "Both", "None", "None"]', 2, 'Clinical diagnosis. (Mont Reid Ch. 8)'),
    (v_topic_id, '107: "Pulsus Paradoxus" = ?', '["Drop in SBP > 10 mmHg on inspiration", "Tamponade", "Both", "None"]', 2, 'Physical exam. (Schwartz''s Ch. 7)'),
    (v_topic_id, '108: "Tracheobronchial injury" - sign? ', '["Massive air leak after chest tube", "Both", "None", "None"]', 0, 'Diagnosis. (de Virgilio Ch. 2)'),
    (v_topic_id, '109: "Aortic Rupture" - Chest X-ray? ', '["Widened mediastinum (> 8 cm)", "Blurred aortic knob", "Both", "None"]', 2, 'Screening. (Mont Reid Ch. 8)'),
    (v_topic_id, '110: "Massive Transfusion" - Complication? ', '["Hypocalcemia / Hypothermia / Hyperkalemia / Alkalosis", "All", "None", "None"]', 1, 'Risks. (Schwartz''s Ch. 7)'),
    (v_topic_id, '111: "FAST" - subxiphoid view? ', '["Checks for pericardial fluid", "Both", "None", "None"]', 0, 'Anatomy. (de Virgilio Ch. 2)'),
    (v_topic_id, '112: "FAST" - Morrison''s Pouch? ', '["RUQ (Between Liver and Kidney)", "Both", "None", "None"]', 0, 'Anatomy. (Mont Reid Ch. 8)'),
    (v_topic_id, '113: "DPL" - aspiration of bile/food/feces? ', '["Positive (Immediate surgery)", "Both", "None", "None"]', 0, 'Diagnosis. (Schwartz''s Ch. 7)'),
    (v_topic_id, '114: "Head Trauma" - Midline shift? ', '["> 5 mm requires surgery", "True", "Both", "None"]', 2, 'Neurosurgery. (de Virgilio Ch. 2)'),
    (v_topic_id, '115: "Basilar Skull Fracture" - signs? ', '["Raccoon eyes / Battle sign / CSF rhinorrhea", "All", "None", "None"]', 1, 'Clinical warning. (Mont Reid Ch. 8)'),
    (v_topic_id, '116: "Cervical Spine" - NEXUS criteria? ', '["Rule out C-spine without imaging", "True", "Both", "None"]', 2, 'Standard. (Schwartz''s Ch. 7)'),
    (v_topic_id, '117: "Jefferson Fracture" = ?', '["C1 burst fracture", "Both", "None", "None"]', 0, 'Eponym. (de Virgilio Ch. 2)'),
    (v_topic_id, '118: "Hangman Fracture" = ?', '["C2 fracture (pars interarticularis)", "Both", "None", "None"]', 0, 'Eponym. (Mont Reid Ch. 8)'),
    (v_topic_id, '119: "Blunt Cardiac Injury" - EKG? ', '["Tachycardia / PVCs / New RBBB", "All", "None", "None"]', 1, 'Monitoring. (Schwartz''s Ch. 7)'),
    (v_topic_id, '120: "Blunt Cardiac Injury" - Echo? ', '["Wall motion abnormality", "Both", "None", "None"]', 0, 'Diagnosis. (de Virgilio Ch. 2)'),
    (v_topic_id, '121: "Diaphragm Injury" - X-ray? ', '["Stomach in chest", "Both", "None", "None"]', 0, 'Imaging. (Mont Reid Ch. 8)'),
    (v_topic_id, '122: "Duodenal Injury" - Retroperitoneal air? ', '["Sign of rupture", "Both", "None", "None"]', 0, 'Imaging. (Schwartz''s Ch. 7)'),
    (v_topic_id, '123: "Pancreatic Injury" - treatment? ', '["If ductal injury, distal pancreatectomy", "Both", "None", "None"]', 0, 'Management. (de Virgilio Ch. 4)'),
    (v_topic_id, '124: "Urethral Injury" - types? ', '["Posterior (Pelvic fx) / Anterior (Saddle)", "Both", "None", "None"]', 2, 'Urology. (Mont Reid Ch. 8)'),
    (v_topic_id, '125: "Bladder Rupture" - Extraperitoneal? ', '["Treat with Foley (usually)", "Both", "None", "None"]', 0, 'Management. (Schwartz''s Ch. 41)'),
    (v_topic_id, '126: "Bladder Rupture" - Intraperitoneal? ', '["Requires surgical repair", "Both", "None", "None"]', 0, 'Management. (de Virgilio Ch. 32)'),
    (v_topic_id, '127: "Burns" - Parkland fluid? ', '["Lactated Ringer''s (LR)", "Both", "None", "None"]', 0, 'Choice. (Mont Reid Ch. 8)'),
    (v_topic_id, '128: "Burns" - Curlling Ulcer? ', '["Stress ulcer in stomach/duodenum", "Both", "None", "None"]', 0, 'Complication. (Schwartz''s Ch. 8)'),
    (v_topic_id, '129: "Burns" - Marjolin Ulcer? ', '["SCC arising in a chronic burn scar", "Both", "None", "None"]', 0, 'Oncology. (de Virgilio Ch. 6)'),
    (v_topic_id, '130: "Chemical Burn" - first step? ', '["Irrigate with WATER (lots of it)", "Neutralize", "Both", "None"]', 0, 'Immediate care. (Mont Reid Ch. 8)'),
    (v_topic_id, '131: "Hydrofluoric Acid" - treatment? ', '["Calcium Gluconate gel", "Both", "None", "None"]', 0, 'Specific antidote. (Schwartz''s Ch. 8)'),
    (v_topic_id, '132: "Compartment Syndrome" - 1st symptom?', '["Pain out of proportion to exam", "Loss of pulse (Late)", "Both", "None"]', 0, 'Warning. (de Virgilio Ch. 3)'),
    (v_topic_id, '133: "Rhabdomyolysis" - urine? ', '["Tea-colored / Heme positive but no RBCs", "Both", "None", "None"]', 2, 'Labs. (Mont Reid Ch. 8)'),
    (v_topic_id, '134: "Rhabdo" - treatment? ', '["Aggressive IV fluids (target 200-300 mL/hr urine)", "Both", "None", "None"]', 0, 'Management. (Schwartz''s Ch. 7)'),
    (v_topic_id, '135: "Hypothermia" - J-wave of Osborn? ', '["EKG finding", "True", "Both", "None"]', 2, 'Physiology. (de Virgilio Ch. 2)'),
    (v_topic_id, '136: "Coagulopathy" of trauma? ', '["Dilution / Consumption / Hypothermia / Acidosis", "All", "None", "None"]', 1, 'Mechanism. (Mont Reid Ch. 8)'),
    (v_topic_id, '137: "REBOA" = ?', '["Resuscitative Endovascular Balloon Occlusion of the Aorta", "Both", "None", "None"]', 0, 'New technology. (Schwartz''s Ch. 7)'),
    (v_topic_id, '138: "SOFA" - components? ', '["Resp, Coag, Liver, CV, CNS, Renal", "True", "Both", "None"]', 2, 'Score. (de Virgilio Ch. 1)'),
    (v_topic_id, '139: "APACHE II" - uses? ', '["Predicts ICU mortality", "Both", "None", "None"]', 0, 'Score. (Mont Reid Ch. 8)'),
    (v_topic_id, '140: "Ventilator" - PEEP? ', '["Positive End-Expiratory Pressure", "Recruits alveoli / Improves oxygenation", "Both", "None"]', 2, 'Setting. (Schwartz''s Ch. 5)'),
    (v_topic_id, '141: "Ventilator" - FiO2? ', '["Fraction of inspired oxygen", "Both", "None", "None"]', 0, 'Setting. (de Virgilio Ch. 1)'),
    (v_topic_id, '142: "Ventilator" - Tidal Volume? ', '["Volume per breath", "Both", "None", "None"]', 0, 'Setting. (Mont Reid Ch. 8)'),
    (v_topic_id, '143: "Ventilator" - Assist Control (AC)? ', '["Fixed volume for every breath", "Both", "None", "None"]', 0, 'Mode. (Schwartz''s Ch. 5)'),
    (v_topic_id, '144: "Ventilator" - Pressure Support (PS)? ', '["Augments patient''s own breath", "Used for weaning", "Both", "None"]', 2, 'Mode. (de Virgilio Ch. 1)'),
    (v_topic_id, '145: "Autonomic Dysreflexia" - level? ', '["Injuries above T6", "Extreme HTN in response to stimulus", "Both", "None"]', 2, 'Complication. (Mont Reid Ch. 8)'),
    (v_topic_id, '146: "Propofol" - side effect? ', '["Hypotension / PRIS (infusion syndrome)", "Both", "None", "None"]', 2, 'Medication. (Schwartz''s Ch. 5)'),
    (v_topic_id, '147: "Etomidate" - side effect? ', '["Adrenal suppression", "Both", "None", "None"]', 0, 'Medication. (de Virgilio Ch. 2)'),
