-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'trauma-critical-care' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: ATLS Primary Survey and Airway

    -- SECTION 2: Circulation and Shock


    -- SECTION 3: Specific Injuries and Burns
    (v_topic_id, '21: "Epidural Hematoma" classically presents with a "Lucid Interval" and shows a ____ shape on CT.', '["Crescent", "Lenticular (Biconvex)", "Irregular", "None"]', 1, 'Usually due to injury of the Middle Meningeal Artery. (Schwartz''s Ch. 7)'),
    (v_topic_id, '22: "Subdural Hematoma" is caused by tearing of ____ and shows a ____ shape on CT.', '["Arteries; Lenticular", "Bridging veins; Crescent", "Veins; Star", "None"]', 1, 'More common in the elderly and alcoholics. (de Virgilio Ch. 2)'),
    (v_topic_id, '23: "Cushing''s Triad" (sign of increased ICP) includes Hypertension, Bradycardia, and ____.', '["Tachypnea", "Irregular respirations (Cheyne-Stokes)", "Fever", "None"]', 1, 'A late and ominous sign. (Mont Reid Ch. 8)'),
    (v_topic_id, '24: A "Pelvic Fracture" with significant bleeding is best stabilized initially with a:', '["Cast", "Pelvic Binder (at the level of greater trochanters)", "Bed rest", "None"]', 1, 'Reduces pelvic volume to tamponade bleeding. (Schwartz''s Ch. 7)'),
    (v_topic_id, '25: According to the "Rule of 9s," the entire right leg of an adult accounts for ____% TBSA.', '["9", "18", "27", "None"]', 1, 'Front = 9, Back = 9. (de Virgilio Ch. 6)'),
    (v_topic_id, '26: The "Parkland Formula" for burn resuscitation calculates the fluid for the first 24 hours as 4 mL x weight (kg) x ____.', '["Age", "% TBSA of 2nd/3rd degree burns", "Blood pressure", "None"]', 1, 'Give half in the first 8 hours. (Mont Reid Ch. 8)'),
    (v_topic_id, '27: "Escharotomy" is indicated in circumferential burns if there is evidence of:', '["Infection", "Compartment syndrome / Impaired distal perfusion", "Pain", "None"]', 1, 'Cuts through the burnt tissue (eschar) to release pressure. (Schwartz''s Ch. 8)'),
    (v_topic_id, '28: What is the leading cause of death in burn patients "after" the first 24 hours?', '["Shock", "Infection (Sepsis)", "Dehydration", "None"]', 1, 'Loss of skin barrier. (de Virgilio Ch. 6)'),
    (v_topic_id, '29: "Silver Sulfadiazine" (Silvadene) is a common topical antibiotic for burns but can cause which side effect?', '["Hearing loss", "Transient Leukopenia", "Metabolic acidosis", "None"]', 1, 'Mafenide acetate (Sulfamylon) can cause metabolic acidosis. (Mont Reid Ch. 8)'),
    (v_topic_id, '30: "Diagnostic Peritoneal Lavage" (DPL) is considered "Positive" if > ____ RBCs/mm³ are aspirated.', '["1,000", "10,000", "100,000", "None"]', 2, 'Largely replaced by FAST and CT. (Schwartz''s Ch. 7)'),

    -- SECTION 4: Critical Care and Physiology
    (v_topic_id, '31: "Sepsis" is defined as life-threatening organ dysfunction caused by a dysregulated host response to infection, indicated by a ____ score >= 2.', '["GCS", "SOFA (Sequential Organ Failure Assessment)", "APACHE", "None"]', 1, 'Replaced older SIRS criteria. (de Virgilio Ch. 1)'),
    (v_topic_id, '32: "Septic Shock" requires vasopressors to maintain MAP >= 65 and a serum lactate > ____ mmol/L despite fluid resuscitation.', '["1", "2", "4", "None"]', 1, 'Indicates cellular/metabolic dysfunction. (Schwartz''s Ch. 5)'),
    (v_topic_id, '33: "ARDS" (Acute Respiratory Distress Syndrome) is characterized by bilateral opacities and a PaO2/FiO2 ratio < ____.', '["100", "200", "300", "400"]', 2, 'In the absence of heart failure/fluid overload. (Mont Reid Ch. 8)'),
    (v_topic_id, '34: What is the preferred initial ventilator strategy for ARDS?', '["High tidal volumes", "Low tidal volume ventilation (6 mL/kg) and High PEEP", "High FiO2 only", "None"]', 1, 'Reduces ventilator-associated lung injury (VALI). (Schwartz''s Ch. 5)'),
    (v_topic_id, '35: "Anion Gap" calculation = Na - (Cl + ____).', '["K", "HCO3", "Glucose", "None"]', 1, 'Normal is ~10-12. (de Virgilio Ch. 1)'),
    (v_topic_id, '36: "MUDPILES" is a mnemonic for elevated anion gap metabolic acidosis. What does "L" stand for?', '["Lidocaine", "Lactate", "Lithium", "None"]', 1, 'Very common in trauma/shock. (Mont Reid Ch. 8)'),
    (v_topic_id, '37: "Hypokalemia" on EKG is associated with flattened T-waves and the presence of ____.', '["Delta waves", "U-waves", "Peaked T-waves", "None"]', 1, 'Peaked T-waves are seen in Hyperkalemia. (Schwartz''s Ch. 11)'),
    (v_topic_id, '38: Which electrolyte abnormality potentiates "Digoxin" toxicity?', '["Hyperkalemia", "Hypokalemia", "Hypernatremia", "None"]', 1, 'Potassium competes with digoxin for the Na/K ATPase pump. (de Virgilio Ch. 1)'),
    (v_topic_id, '39: "Central Venous Pressure" (CVP) is a rough measure of:', '["Left atrial pressure", "Right atrial pressure / Preload", "Afterload", "None"]', 1, 'Normal is 2-6 mmHg. (Mont Reid Ch. 8)'),
    (v_topic_id, '40: The "PCO2" on an ABG is the primary measure of ____.', '["Oxygenation", "Alveolar Ventilation", "Metabolism", "None"]', 1, 'High PCO2 indicates hypoventilation. (Schwartz''s Ch. 5)'),

    -- SECTION 5: Trauma Potpourri and Ethics
    (v_topic_id, '41: A "Boxer''s Fracture" is a fracture of the neck of the ____ metacarpal.', '["1st", "2nd", "5th", "None"]', 2, 'Common from punching a wall. (de Virgilio Ch. 34)'),
    (v_topic_id, '42: "Colles'' Fracture" is a distal radius fracture with ____ displacement.', '["Ventral", "Dorsal (''dinner fork'' deformity)", "None", "None"]', 1, 'Smith''s fracture is ventral displacement. (Mont Reid Ch. 14)'),
    (v_topic_id, '43: "Compartment Syndrome" in the leg is most common in which compartment?', '["Anterior", "Lateral", "Deep Posterior", "None"]', 0, 'Contains the deep peroneal nerve. (Schwartz''s Ch. 39)'),
    (v_topic_id, '44: "Fat Embolism Syndrome" typically occurs 24-72 hours after which injury?', '["Head trauma", "Long bone (Femur) or Pelvic fracture", "Burn", "None"]', 1, 'Triad: Hypoxia, Petechial rash, Confusion. (de Virgilio Ch. 3)'),
    (v_topic_id, '45: "Air Embolism" can occur with central line placement. The patient should be placed in which position?', '["Trendelenburg and Left Lateral Decubitus (Durant''s)", "Reverse Trendelenburg", "Sitting", "None"]', 0, 'Traps air in the right ventricle. (Mont Reid Ch. 8)'),
    (v_topic_id, '46: In an emergency, if a patient is unable to give consent and no surrogate is available:', '["Wait for court", "Assume implied consent for life-saving care", "Do nothing", "None"]', 1, 'Standard of care in trauma. (Schwartz''s Ch. 48)'),
    (v_topic_id, '47: What is the most common cause of "Cardiogenic Shock" in trauma?', '["MI", "Myocardial Contusion", "Tamponade", "Valvular rupture"]', 1, 'Heart is bruised against the sternum. (de Virgilio Ch. 3)'),
    (v_topic_id, '48: "Massive Transfusion" can lead to which metabolic abnormality due to citrate?', '["Hypercalcemia", "Hypocalcemia", "Hyperkalemia", "None"]', 1, 'Citrate binds ionized calcium. (Mont Reid Ch. 8)'),
    (v_topic_id, '49: "Brown-Sequard Syndrome" (spinal cord hemisection) results in loss of motor on the ____ side and pain/temp on the ____ side.', '["Ipsilateral; Contralateral", "Contralateral; Ipsilateral", "Same; Same", "None"]', 0, 'Classic cross-over of spinothalamic tract. (Schwartz''s Ch. 7)'),
    (v_topic_id, '50: "Tracheal Deviation" away from the affected side is a sign of:', '["Simple PTX", "Tension Pneumothorax", "Pneumonia", "None"]', 1, 'Indicates mediastinal shift. (de Virgilio Ch. 2)');

    -- Batch 2: 51-150 (Deep Dive Trauma & Critical Care)

    -- Batch 3: 101-350 (Rapid Fire and Advanced Critical Care)

END $$;

COMMIT;
